"""PaySetu state: hand-written ledger plus payments generated by other apps, numbered in time order."""

from __future__ import annotations

from typing import Any

from .content import unique

PAYEE_FIELDS = ("payee_id", "name", "upi_id", "phone")
TXN_FIELDS = (
    "timestamp",
    "direction",
    "amount",
    "counterparty_name",
    "source_id",
    "category",
    "status",
    "counterparty_upi_id",
    "reference_app",
    "reference_id",
    "note",
)


def build_paysetu(content: dict[str, Any], generated: list[dict[str, Any]]) -> tuple[dict[str, Any], dict[str, str]]:
    """Return (PaySetu state, map from local transaction keys to final txn_ids)."""
    sources = unique(content["sources"], "source_id", "payment source")
    entries = [{**txn, "key": txn["txn_id"]} for txn in content.get("transactions", [])] + list(generated)
    keys = [entry["key"] for entry in entries]
    if len(keys) != len(set(keys)):
        raise ValueError("Duplicate transaction key")
    entries.sort(key=lambda entry: (entry["timestamp"], entry["key"]))
    ids = {entry["key"]: f"PS-TXN-{index:05d}" for index, entry in enumerate(entries, start=1)}
    transactions = {}
    for entry in entries:
        if entry["source_id"] not in sources:
            raise ValueError(f"Transaction {entry['key']} uses unknown source {entry['source_id']}")
        txn_id = ids[entry["key"]]
        record = {field: entry.get(field) for field in TXN_FIELDS}
        record["status"] = record["status"] or "success"
        record["note"] = record["note"] or ""
        record["txn_id"] = txn_id
        record["refund_of"] = ids[entry["refund_of_key"]] if entry.get("refund_of_key") else None
        transactions[txn_id] = record
    payees = {
        payee["payee_id"]: {field: payee.get(field, "") for field in PAYEE_FIELDS}
        for payee in unique(content.get("payees", []), "payee_id", "payee").values()
    }
    requests = unique(content.get("requests", []), "request_id", "payment request")
    state = {
        "id_counters": {
            "PS-TXN": len(transactions),
            "PS-PAYEE": len(payees),
            "PS-REQ": len(requests),
        },
        "sources": {
            source_id: {"upi_id": None, "balance": 0, "available_limit": 0, "is_default": False, **source}
            for source_id, source in sources.items()
        },
        "payees": payees,
        "transactions": transactions,
        "requests": requests,
    }
    return state, ids
